import fs from 'node:fs/promises';
import {readProgressMeasurement,createProgressMilestones} from './progress-milestones.mjs';
import path from 'node:path';
import {constants} from 'node:fs';
import {createHash} from 'node:crypto';
import {pathToFileURL,fileURLToPath} from 'node:url';
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const hex=value=>/^[a-f0-9]{64}$/.test(value||'');
const absolute=value=>typeof value==='string'&&path.isAbsolute(value)&&path.resolve(value)!=='/'&&path.resolve(value)===value;
// Non-circular scope binding: config digest/commit echo are separately bound by
// the immutable full plan, and cannot be included in the config's own contract.
export function watchPlanContractSha256(plan){const projection=Object.fromEntries(Object.keys(plan).filter(k=>!['configSha256','authorizeCommit'].includes(k)).sort().map(k=>[k,plan[k]]));return hash(JSON.stringify(projection));}
export function validateWatchPlan(p){
 if(p?.version!==1||!['preflight','prepare','commit'].includes(p.mode))throw Error('controller_plan_scope');
 for(const k of ['entry','entrySha256','watchdog','watchdogSha256','config','configSha256','loader','loaderSha256','evidenceDirectory','workDirectory','temporaryDirectory','publisherRoot'])if(k.endsWith('Sha256')?!hex(p[k]):!absolute(p[k]))throw Error('controller_plan_binding');
 for(const k of ['rssBytes','diskBytes','wallMs','heapMiB'])if(!Number.isSafeInteger(p[k])||p[k]<=0)throw Error('controller_budget');
 if(p.heapMiB*1024**2>=p.rssBytes||p.wallMs>6*3600*1000||!Array.isArray(p.diskRoots)||!p.diskRoots.length||p.diskRoots.length>4||p.diskRoots.some(x=>!absolute(x)))throw Error('controller_budget');
 for(const d of [p.workDirectory,p.temporaryDirectory,p.evidenceDirectory])if(!p.diskRoots.some(root=>d===root||d.startsWith(root+path.sep)))throw Error('controller_uncovered_output');
 if(p.mode==='commit'?p.authorizeCommit!==p.configSha256:p.authorizeCommit!==undefined)throw Error('controller_commit_scope');
 return Object.freeze({...p,diskRoots:Object.freeze([...p.diskRoots])});
}
const stages=new Set(['load','retention','merge','audit','canonical','spool','index','raw','v2','readiness','commit','source','capture']);
const checkpoints=new Set(['archive-local-verified','converted-input-verified','internal_start','current_read_models_start','current_read_models_written','all_read_models_verified','verify_details',...['all','china','japan','korea','uae','europe','georgia'].map(m=>'verify_projection_'+m)]);
const events=new Set(['begin','progress','end','failed']);
export function publicProgress(value){
 if(!value||!stages.has(value.stage)||!events.has(value.event))return null;
 const result={stage:value.stage,event:value.event};if(checkpoints.has(value.checkpoint))result.checkpoint=value.checkpoint;
 for(const k of ['elapsedMs','phaseElapsedMs','rss','heapUsed','numericUsedRows','numericNewRows','inputRows','outputRows','readBytes','writeBytes','getCount','headCount','putCount','diskReadCount','reclaimedBytes','files','rows','bytes','objects','count','diskBytes'])if(Number.isSafeInteger(value[k])&&value[k]>=0)result[k]=value[k];
 const measurement=readProgressMeasurement(value);if(measurement)Object.assign(result,measurement);
 return result;
}
async function boundFile(file,digest,max=1024*1024){
 if(await fs.realpath(file)!==file)throw Error('controller_symlink');
 const fd=await fs.open(file,constants.O_RDONLY|constants.O_NOFOLLOW);
 try{const before=await fd.stat();if(!before.isFile()||before.size>max)throw Error('controller_file_cap');const b=Buffer.alloc(before.size);let n=0;while(n<b.length){const r=await fd.read(b,n,b.length-n,n);if(!r.bytesRead)throw Error('controller_short_file');n+=r.bytesRead;}const after=await fd.stat();if((await fd.read(Buffer.alloc(1),0,1,n)).bytesRead||after.size!==before.size||after.ino!==before.ino||after.mtimeMs!==before.mtimeMs||hash(b)!==digest)throw Error('controller_file_binding');return b;}finally{await fd.close();}
}
export async function runBounded(planFile,planSha){
 if(!absolute(planFile)||!hex(planSha))throw Error('controller_arguments');
 const plan=validateWatchPlan(JSON.parse(await boundFile(planFile,planSha)));
 for(const[p,h]of [[plan.entry,plan.entrySha256],[plan.watchdog,plan.watchdogSha256],[plan.config,plan.configSha256],[plan.loader,plan.loaderSha256]])await boundFile(p,h,16*1024*1024);
 const config=JSON.parse(await boundFile(plan.config,plan.configSha256));if(config.profile==='china-saved-progressive-v1'){const ownFile=fileURLToPath(import.meta.url),ownHash=hash(await fs.readFile(ownFile));if(config.launcherContract?.wrapperSha256!==ownHash||config.launcherContract?.watchdogSha256!==plan.watchdogSha256||config.launcherContract?.planSha256!==watchPlanContractSha256(plan))throw Error('controller_resource_contract');}for(const k of ['publisherRoot','workDirectory','temporaryDirectory'])if(config[k]!==plan[k])throw Error('controller_config_path_mismatch');
 for(const d of [plan.evidenceDirectory,plan.temporaryDirectory]){const st=await fs.lstat(d);if(!st.isDirectory()||st.isSymbolicLink()||await fs.realpath(d)!==d)throw Error('controller_evidence_directory');}
 const evidenceStat=await fs.lstat(plan.evidenceDirectory);if(evidenceStat.mode&0o077)throw Error('controller_evidence_not_private');
 if(!absolute(config.runtimeRoot))throw Error('controller_runtime_path');
 const dataPaths=[path.join(config.publisherRoot,'data'),path.join(config.runtimeRoot,'data'),...(config.restoredDirectory?[config.restoredDirectory]:[])];
 for(const d of dataPaths){if(!absolute(d))throw Error('controller_data_path');if(!plan.diskRoots.some(root=>d===root||d.startsWith(root+path.sep)))throw Error('controller_uncovered_data');}
 const {watchNode}=await import(pathToFileURL(plan.watchdog));
 const stopFile=path.join(plan.evidenceDirectory,'fatal-stop.json');
 const args=['--max-old-space-size='+plan.heapMiB,'--import',plan.loader,plan.entry,'--mode',plan.mode,'--config',plan.config,'--config-sha256',plan.configSha256,'--evidence-directory',plan.evidenceDirectory];
 if(plan.mode==='commit')args.push('--authorize-commit',plan.authorizeCommit);
 let pollPromise=null,last='',pollCode=null,seenLines=0;const milestones=createProgressMilestones();
 const poll=()=>{if(pollPromise)return pollPromise;pollPromise=(async()=>{try{const file=path.join(plan.workDirectory,'progress.jsonl');if(await fs.realpath(file)!==file)throw Error('controller_progress_symlink');const fd=await fs.open(file,constants.O_RDONLY|constants.O_NOFOLLOW);let raw;try{const before=await fd.stat();if(!before.isFile()||before.size>1048576)throw Error('controller_progress_cap');const buffer=Buffer.alloc(1048577);let n=0;while(n<buffer.length){const r=await fd.read(buffer,n,buffer.length-n,n);if(!r.bytesRead)break;n+=r.bytesRead;}if(n>1048576)throw Error('controller_progress_cap');raw=buffer.subarray(0,n).toString('utf8');}finally{await fd.close();}const lines=raw.split('\n');if(lines.length-1<seenLines)throw Error('controller_progress_truncated');let latest=null;for(let i=seenLines;i<lines.length-1;i++){let value;try{value=publicProgress(JSON.parse(lines[i]));}catch{pollCode='progress_invalid';milestones.invalidate();continue;}if(!value)continue;latest=value;try{const milestone=milestones.observe(value);if(milestone)console.log(JSON.stringify({stage:value.stage,event:'progress',...milestone}));}catch{pollCode='progress_invalid';latest={...value};for(const k of ['phaseKey','progressCompleted','progressTotal','progressUnit'])delete latest[k];}}seenLines=lines.length-1;if(latest){const text=JSON.stringify(latest);if(text!==last){console.log(text);last=text;}}}catch(e){if(e.code!=='ENOENT'||seenLines>0){pollCode='progress_unavailable';milestones.invalidate();}}})().finally(()=>{pollPromise=null;});return pollPromise;};
 const timer=setInterval(()=>void poll(),10000);let result;
 try{result=await watchNode({args,cwd:plan.publisherRoot,env:{TMPDIR:plan.temporaryDirectory},rssBytes:plan.rssBytes,wallMs:plan.wallMs,diskRoots:plan.diskRoots,diskBytes:plan.diskBytes,outputBytes:1048576,stopFile});}
 finally{clearInterval(timer);if(pollPromise)await pollPromise;await poll();}
 const final={version:1,...result,progressDiagnostic:pollCode,mode:plan.mode,configSha256:plan.configSha256,planSha256:planSha,scope:'sampled owned-process and disk gate; not publication acceptance'};
 await fs.writeFile(path.join(plan.evidenceDirectory,'controller-resource.json'),JSON.stringify(final,null,2),{flag:'wx',mode:0o600});console.log(JSON.stringify(final));return final;
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){try{const r=await runBounded(...process.argv.slice(2));process.exitCode=r.ok?0:1;}catch{console.error(JSON.stringify({ok:false,code:'bounded_controller_failed',reconciliationRequired:true}));process.exitCode=1;}}

const phases=Object.freeze({'source-fresh':'rows','capture-objects':'objects','capture-bytes':'bytes','merge-rows':'rows','numeric-china':'rows','numeric-used':'rows','numeric-new':'rows','immutable-objects':'objects','immutable-bytes':'bytes'});
const fields=['phaseKey','progressCompleted','progressTotal','progressUnit'];
export function readProgressMeasurement(value){
 if(!fields.some(k=>Object.hasOwn(value,k)))return null;
 const {phaseKey,progressCompleted,progressTotal,progressUnit}=value;
 if(!Object.hasOwn(phases,phaseKey)||phases[phaseKey]!==progressUnit||!Number.isSafeInteger(progressCompleted)||!Number.isSafeInteger(progressTotal)||progressCompleted<0||progressTotal<0||progressCompleted>progressTotal)throw Error('progress_measurement_invalid');
 return {phaseKey,progressCompleted,progressTotal,progressUnit};
}
export function createProgressMilestones(){
 const states=new Map();let invalid=false;
 return Object.freeze({invalidate(){invalid=true;},observe(value){
  if(invalid)throw Error('progress_stream_unavailable');
  let m;try{m=readProgressMeasurement(value);}catch(error){invalid=true;throw error;}if(!m)return null;
  const old=states.get(m.phaseKey);
  if(old?.failed)throw Error('progress_phase_unavailable');
  if(old&&(old.total!==m.progressTotal||old.unit!==m.progressUnit||m.progressCompleted<old.completed)){
   old.failed=true;throw Error('progress_denominator_or_order_changed');
  }
  // BigInt avoids rounding large safe-integer counts into a false 100%.
  const milestone=m.progressTotal===0?0:Number(BigInt(m.progressCompleted)*10n/BigInt(m.progressTotal))*10;
  states.set(m.phaseKey,{total:m.progressTotal,unit:m.progressUnit,completed:m.progressCompleted,milestone,failed:false});
  if(m.progressTotal===0||milestone===0||milestone<=(old?.milestone||0))return null;
  return {...m,milestonePercent:milestone,scope:'measured phase only; not overall publication readiness'};
 }});
}

import {spawn} from 'node:child_process';
import fs from 'node:fs/promises';
import {constants} from 'node:fs';
import path from 'node:path';

export const FATAL_STOP_BASENAME='fatal-stop.json';
const fatalCodes=new Set(['resource_renewal_failed','source_epoch_failed','fatal_marker_write_failed']);
export async function createFatalStopReader(stopFile){
 if(typeof stopFile!=='string'||!path.isAbsolute(stopFile)||path.resolve(stopFile)!==stopFile||path.basename(stopFile)!==FATAL_STOP_BASENAME)throw Error('watchdog_stop_path');
 const directory=path.dirname(stopFile),initial=await fs.lstat(directory);
 if(!initial.isDirectory()||initial.isSymbolicLink()||initial.mode&0o077||await fs.realpath(directory)!==directory)throw Error('watchdog_stop_directory');
 return async()=>{
  let handle,directoryHandle;try{
   const current=await fs.lstat(directory);if(!current.isDirectory()||current.isSymbolicLink()||current.dev!==initial.dev||current.ino!==initial.ino||current.mode&0o077||await fs.realpath(directory)!==directory)return{present:true,valid:false,code:'stop_directory_changed'};
   directoryHandle=await fs.open(directory,constants.O_RDONLY|constants.O_DIRECTORY|constants.O_NOFOLLOW);const anchor=await directoryHandle.stat();if(anchor.dev!==initial.dev||anchor.ino!==initial.ino)return{present:true,valid:false,code:'stop_directory_changed'};
   try{handle=await fs.open(`/proc/self/fd/${directoryHandle.fd}/${FATAL_STOP_BASENAME}`,constants.O_RDONLY|constants.O_NOFOLLOW|constants.O_NONBLOCK);}catch(e){if(e.code==='ENOENT')return{present:false};return{present:true,valid:false,code:'stop_file_unreadable'};}
   const before=await handle.stat();if(!before.isFile()||before.nlink!==1||before.size>1024||before.mode&0o077)return{present:true,valid:false,code:'stop_file_shape'};
   const buffer=Buffer.alloc(1025);let n=0;while(n<buffer.length){const r=await handle.read(buffer,n,buffer.length-n,n);if(!r.bytesRead)break;n+=r.bytesRead;}
   const after=await handle.stat();if(n>1024||n!==before.size||after.size!==before.size||after.mtimeMs!==before.mtimeMs||after.ctimeMs!==before.ctimeMs)return{present:true,valid:false,code:'stop_file_changed'};
   let v;try{v=JSON.parse(buffer.subarray(0,n).toString('utf8'));}catch{return{present:true,valid:false,code:'stop_file_invalid'};}
   const valid=v&&Object.getPrototypeOf(v)===Object.prototype&&Object.keys(v).sort().join(',')==='code,version'&&v.version===1&&fatalCodes.has(v.code);
   return{present:true,valid:Boolean(valid),code:valid?v.code:'stop_file_invalid'};
  }catch{return{present:true,valid:false,code:'stop_file_unreadable'};}finally{await handle?.close().catch(()=>{});await directoryHandle?.close().catch(()=>{});}
 };
}

export async function readOwnedDisk(roots, stopped=()=>false) {
  let bytes=0,entries=0,discovered=roots.length;const pending=[...roots];
  while(pending.length){
    if(stopped())return {bytes,entries,interrupted:true};
    if(++entries>100000)throw Error('disk_entry_limit');
    const file=pending.pop();let s;
    try{s=await fs.lstat(file);}catch(e){if(e.code==='ENOENT')continue;throw e;}
    if(s.isSymbolicLink())throw Error('disk_symlink');
    if(s.isDirectory()){for await(const entry of await fs.opendir(file)){if(++discovered>100000)throw Error('disk_entry_limit');pending.push(path.join(file,entry.name));}}
    else if(s.isFile())bytes+=Math.max(s.size,s.blocks*512);
    else throw Error('disk_file_type');
  }
  return {bytes,entries,interrupted:false};
}

// Linux local acceptance harness. RSS is sampled and summed (shared pages may be
// counted twice); this is conservative evidence, not a cgroup hard memory limit.
export function parseProcStat(stat){const end=stat.lastIndexOf(')');if(end<0)throw Error('proc_stat_invalid');const fields=stat.slice(end+2).trim().split(/\s+/);if(fields.length<3||!/^[A-Za-z]$/.test(fields[0])||!/^\d+$/.test(fields[2])||!Number.isSafeInteger(Number(fields[2])))throw Error('proc_stat_invalid');return{state:fields[0],group:Number(fields[2])};}

export async function readGroupRss(group, proc='/proc') {
  let bytes=0, processes=0;
  processLoop: for (const id of await fs.readdir(proc)) {
    if (!/^\d+$/.test(id)) continue;
    let stat;
    try { stat=await fs.readFile(`${proc}/${id}/stat`,'utf8'); }
    catch(e) { if (e.code==='ENOENT'||e.code==='ESRCH') continue; throw e; }
    const first=parseProcStat(stat);
    if(first.group!==group) continue; // field 5, pgrp
    // A process may drop its address space before /proc reports Z. Never
    // accept a live task without RSS: bounded rereads must prove RSS, Z/X,
    // or disappearance. Persistent unknown measurement still fails closed.
    let rss=null;
    for(let attempt=0;attempt<3;attempt++){
      let status;
      try {status=await fs.readFile(`${proc}/${id}/status`,'utf8');}
      catch(e){if(e.code==='ENOENT'||e.code==='ESRCH')continue processLoop;throw e;}
      const match=status.match(/^VmRSS:\s+(\d+)\s+kB$/m);
      if(match){rss=Number(match[1])*1024;break;}
      if(/^State:\s+[ZX](?:\s|$)/m.test(status)){rss=0;break;}
      let current;
      try{current=await fs.readFile(`${proc}/${id}/stat`,'utf8');}
      catch(e){if(e.code==='ENOENT'||e.code==='ESRCH')continue processLoop;throw e;}
      const confirmed=parseProcStat(current);
      if(confirmed.group!==group)continue processLoop;
      if(['Z','X'].includes(confirmed.state)){rss=0;break;}
      if(attempt===2)throw Error('proc_rss_missing');
      await new Promise(resolve=>setTimeout(resolve,1));
    }
    if(rss===null||!Number.isSafeInteger(rss)||rss<0)throw Error('proc_rss_missing');
    bytes+=rss;processes++;
  }
  return {bytes,processes};
}

export function measurementErrorCode(error){const code=String(error?.code||'');if(['EACCES','EPERM','ENOENT','ESRCH','EIO','EMFILE','ENFILE','EINVAL','ENOMEM','EBUSY','ENOTDIR','ELOOP','ETIMEDOUT'].includes(code))return code;const message=String(error?.message||'');return ['proc_stat_invalid','proc_rss_missing','disk_entry_limit','disk_symlink','disk_file_type'].includes(message)?message:'measurement_unknown';}

export async function watchNode({args, cwd, env={}, rssBytes, wallMs,
  sampleMs=100, graceMs=500, outputBytes=1048576,diskRoots=[],diskBytes,diskSampleMs=1000,stopFile}) {
  if(process.platform!=='linux'||!Array.isArray(args)||!args.length) throw Error('watchdog_scope');
  for(const n of[rssBytes,wallMs,sampleMs,graceMs,outputBytes])
    if(!Number.isSafeInteger(n)||n<=0) throw Error('watchdog_budget');
  if(!Array.isArray(diskRoots)||diskRoots.length>4||diskRoots.some(x=>typeof x!=='string'||!path.isAbsolute(x)||path.resolve(x)==='/')||diskRoots.length&&(!Number.isSafeInteger(diskBytes)||diskBytes<=0||!Number.isSafeInteger(diskSampleMs)||diskSampleMs<100))throw Error('watchdog_disk_budget');
  const readStop=stopFile===undefined?null:await createFatalStopReader(stopFile);if(readStop&&(await readStop()).present)throw Error('watchdog_stop_preexisting');
  const start=Date.now();
  const child=spawn(process.execPath,args,{cwd,detached:true,
    env:{...process.env,...env,NODE_OPTIONS:''},stdio:['ignore','pipe','pipe']});
  let fatalStop=null;let measurementFailure=null;const recordMeasurement=(phase,error)=>{measurementFailure??={phase,code:measurementErrorCode(error)};};
  let reason=null, peakRssBytes=0, peakProcesses=0, bytes=0, samples=0, exited=false, timer,peakDiskBytes=0,diskSamples=0;
  const signal=s=>{if(child.pid)try{process.kill(-child.pid,s);}catch(e){if(e.code!=='ESRCH')throw e;}};
  const stop=why=>{if(reason)return;reason=why;signal('SIGTERM');timer=setTimeout(()=>signal('SIGKILL'),graceMs);};
  for(const stream of[child.stdout,child.stderr])stream.on('data',chunk=>{
    bytes+=chunk.length;if(bytes>outputBytes)stop('output_budget');
  });
  const wall=setTimeout(()=>stop('wall_budget'),wallMs);
  const done=new Promise(resolve=>{
    child.once('error',()=>{reason='spawn_failed';exited=true;resolve({code:null,signal:null});});
    child.once('exit',(code,signal)=>{exited=true;resolve({code,signal});});
  });
  const sampler=(async()=>{
    while(!exited){
      if(readStop){const mark=await readStop();if(mark.present){fatalStop=mark;stop(mark.valid?'fatal_stop':'fatal_stop_invalid');}}
      try {const s=await readGroupRss(child.pid);samples++;peakRssBytes=Math.max(peakRssBytes,s.bytes);peakProcesses=Math.max(peakProcesses,s.processes);if(s.bytes>rssBytes)stop('rss_budget');}
      catch(error){recordMeasurement('rss_sampling',error);stop('measurement_failed');}
      if(!exited)await new Promise(r=>setTimeout(r,sampleMs));
    }
  })();
  const diskSampler=(async()=>{
    if(!diskRoots.length)return;
    while(!exited){
      try{const d=await readOwnedDisk(diskRoots,()=>exited);if(!d.interrupted){diskSamples++;peakDiskBytes=Math.max(peakDiskBytes,d.bytes);if(d.bytes>diskBytes)stop('disk_budget');}}
      catch(error){recordMeasurement('disk_sampling',error);stop('disk_measurement_failed');}
      if(!exited)await new Promise(r=>setTimeout(r,diskSampleMs));
    }
  })();
  const result=await done;
  if(readStop){const mark=await readStop();if(mark.present){fatalStop=mark;reason||=mark.valid?'fatal_stop':'fatal_stop_invalid';}}
  clearTimeout(wall);clearTimeout(timer);await sampler;
  try{if((await readGroupRss(child.pid)).bytes>0)reason||='orphan_descendant';}catch(error){recordMeasurement('rss_terminal',error);reason||='measurement_failed';}
  signal('SIGKILL');
  await diskSampler;
  // Parent success with surviving descendants is not accepted; clean the whole
  // owned group even on success. The actual staged child does not detach.
  let survivors=0;
  try{
    const until=Date.now()+1000;
    do {survivors=(await readGroupRss(child.pid)).bytes;if(!survivors)break;await new Promise(r=>setTimeout(r,20));}while(Date.now()<until);
  }catch(error){recordMeasurement('rss_terminal',error);reason||='measurement_failed';}
  if(diskRoots.length)try{const d=await readOwnedDisk(diskRoots);diskSamples++;peakDiskBytes=Math.max(peakDiskBytes,d.bytes);if(d.bytes>diskBytes)reason||='disk_budget';}catch(error){recordMeasurement('disk_terminal',error);reason||='disk_measurement_failed';}
  return {ok:result.code===0&&!reason&&!survivors,...result,reason,measurementFailure,...(fatalStop?{fatalStop}:{}),
    elapsedMs:Date.now()-start,peakRssBytes,peakProcesses,samples,outputBytes:bytes,
    remainingRssBytes:survivors,peakDiskBytes,diskSamples,scope:'sampled sum of owned process-group RSS'};
}

// Exact controller configuration only. Grants no source/session/publication authority.
import fs from 'node:fs/promises';import path from 'node:path';import {createHash} from 'node:crypto';import {fileURLToPath,pathToFileURL} from 'node:url';import {createRequire} from 'node:module';import {execFileSync} from 'node:child_process';
import {watchPlanContractSha256,validateWatchPlan} from './run-bounded.mjs';
const sha=b=>createHash('sha256').update(b).digest('hex'),GiB=1024**3;
const publisherRevision='bb6317bffd1f7b1832681ac78378fe6c3e39e3b5',runtimeRevision='83ff17075e9188dcf227c8752dc064248d5f42e0';
async function bytes(file,max=64*1024**2){if(await fs.realpath(file)!==file)throw Error('materialize_symlink');const h=await fs.open(file,'r');try{const st=await h.stat();if(!st.isFile()||st.size>max)throw Error('materialize_size');const b=await h.readFile();const end=await h.stat();if(b.length!==st.size||end.size!==st.size||end.mtimeMs!==st.mtimeMs)throw Error('materialize_changed');return b;}finally{await h.close();}}
async function put(file,value){await fs.writeFile(file,JSON.stringify(value),{flag:'wx',mode:0o400});return sha(JSON.stringify(value));}
// Only writable pipeline namespaces; immutable npm workspaces legitimately contain symlinks.
export const ownedDiskRoots=({jobRoot,publisherRoot,runtimeRoot})=>[jobRoot,path.join(publisherRoot,'data'),path.join(runtimeRoot,'data'),path.join(publisherRoot,'catalog-staged-budget-report.json')];
export async function materializeJob({jobRoot,publisherRoot,runtimeRoot,packageDirectory,controllerDirectory,expectedManifestSha256,runId,attempt,revision,receiptFile}){
 for(const d of [jobRoot,publisherRoot,runtimeRoot,packageDirectory,controllerDirectory])if(!path.isAbsolute(d)||await fs.realpath(d)!==d)throw Error('materialize_layout');
 if(!/^[a-f0-9]{64}$/.test(expectedManifestSha256)||!/^\d+$/.test(runId)||!/^\d+$/.test(attempt)||!/^[a-f0-9]{40}$/.test(revision))throw Error('materialize_scope');
 if(process.version!=='v24.22.1'||execFileSync('npm',['--version'],{encoding:'utf8'}).trim()!=='11.9.0')throw Error('materialize_toolchain');
 const manifestBytes=await bytes(path.join(packageDirectory,'SOURCE_MANIFEST.json'),16*1024**2);if(sha(manifestBytes)!==expectedManifestSha256)throw Error('materialize_manifest');const m=JSON.parse(manifestBytes);
 if(m.version!==1||m.dynamicSitesReviewed!==true||m.native?.publisher?.revision!==publisherRevision||m.native?.runtime?.revision!==runtimeRevision)throw Error('materialize_native_scope');
