#!/usr/bin/env python3
"""Pinned local artifact extraction, not current archive/lease/source authority.
All writes use descriptor-anchored exclusive opens. Failure preserves partial
private evidence; callers must not treat it as a successfully restored source.
"""
import hashlib, json, os, pathlib, re, stat, sys, zipfile

DIR = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW

def signature(s):
    return (s.st_dev, s.st_ino, s.st_size, s.st_mtime_ns, s.st_ctime_ns)

def digest(f):
    f.seek(0)
    h = hashlib.sha256()
    for chunk in iter(lambda: f.read(1024*1024), b''): h.update(chunk)
    return h.hexdigest()

def extract(source, destination, expected_sha, expected_files, expected_bytes, reserve_bytes=2*1024**3):
    if not re.fullmatch(r'[a-f0-9]{64}', expected_sha): raise ValueError('source_digest')
    for value in (expected_files, expected_bytes, reserve_bytes):
        if type(value) is not int or value < 0: raise ValueError('source_budget')
    if not 1 <= expected_files <= 10000 or not 1 <= expected_bytes <= 8*1024**3: raise ValueError('source_budget')
    source, destination = pathlib.Path(source), pathlib.Path(destination)
    if not source.is_absolute() or not destination.is_absolute() or source.parent.resolve()!=source.parent or destination.parent.resolve()!=destination.parent or destination.name in ('','.','..'): raise ValueError('source_path')
    parent_fd = os.open(destination.parent, DIR)
    source_fd = root_fd = None
    try:
        parent_stat = os.fstat(parent_fd)
        if not stat.S_ISDIR(parent_stat.st_mode): raise ValueError('source_destination')
        def parent_identity():
            named=os.stat(destination.parent, follow_symlinks=False)
            if not stat.S_ISDIR(named.st_mode) or (named.st_dev,named.st_ino)!=(parent_stat.st_dev,parent_stat.st_ino) or destination.parent.resolve()!=destination.parent: raise ValueError('source_parent_changed')
        parent_identity()
        try: os.stat(destination.name,dir_fd=parent_fd,follow_symlinks=False)
        except FileNotFoundError: pass
        else: raise ValueError('source_destination')
        source_fd=os.open(source,os.O_RDONLY|os.O_NOFOLLOW)
        source_initial=os.fstat(source_fd)
        if not stat.S_ISREG(source_initial.st_mode): raise ValueError('source_path')
        with os.fdopen(source_fd,'rb',closefd=False) as f:
            if digest(f)!=expected_sha or signature(os.fstat(source_fd))!=signature(source_initial): raise ValueError('source_digest_changed')
            f.seek(0)
            with zipfile.ZipFile(f) as z:
                infos=z.infolist()
                if len(infos)!=expected_files: raise ValueError('source_inventory_changed')
                names=set();total=0
                for info in infos:
                    name=info.filename;p=pathlib.PurePosixPath(name);mode=info.external_attr>>16
                    if not re.fullmatch(r'[a-zA-Z0-9_./-]+',name) or p.is_absolute() or any(x in ('','.', '..') for x in name.split('/')) or str(p)!=name: raise ValueError('source_member_path')
                    if name in names or info.is_dir() or stat.S_ISLNK(mode) or stat.S_IFMT(mode) not in (0,stat.S_IFREG) or info.flag_bits&1: raise ValueError('source_member_type')
                    if info.file_size<0 or info.file_size>128*1024**2: raise ValueError('source_member_size')
                    names.add(name);total+=info.file_size
                if total!=expected_bytes: raise ValueError('source_inventory_changed')
                disk=os.fstatvfs(parent_fd)
                if disk.f_bavail*disk.f_frsize<total+reserve_bytes: raise ValueError('source_free_space')
                parent_identity();os.mkdir(destination.name,mode=0o700,dir_fd=parent_fd)
                root_fd=os.open(destination.name,DIR,dir_fd=parent_fd);root_stat=os.fstat(root_fd)
                if not stat.S_ISDIR(root_stat.st_mode) or stat.S_IMODE(root_stat.st_mode)&0o077: raise ValueError('source_root_mode')
                def root_identity():
                    parent_identity();named=os.stat(destination.name,dir_fd=parent_fd,follow_symlinks=False)
                    if not stat.S_ISDIR(named.st_mode) or (named.st_dev,named.st_ino)!=(root_stat.st_dev,root_stat.st_ino): raise ValueError('source_root_changed')
                written=0
                for info in infos:
                    root_identity();parts=pathlib.PurePosixPath(info.filename).parts;directory_fd=os.dup(root_fd)
                    try:
                        for component in parts[:-1]:
                            try: os.mkdir(component,mode=0o700,dir_fd=directory_fd)
                            except FileExistsError: pass
                            next_fd=os.open(component,DIR,dir_fd=directory_fd)
                            os.close(directory_fd);directory_fd=next_fd
                        output_fd=os.open(parts[-1],os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600,dir_fd=directory_fd)
                        try:
                            count=0
                            with z.open(info) as inp:
                                while True:
                                    chunk=inp.read(1024*1024)
                                    if not chunk: break
                                    count+=len(chunk)
                                    if count>info.file_size or written+count>expected_bytes: raise ValueError('source_expansion_changed')
                                    view=memoryview(chunk)
                                    while view:
                                        n=os.write(output_fd,view)
                                        if n<=0: raise ValueError('source_short_write')
                                        view=view[n:]
