                        finally: os.close(output_fd)
                    finally: os.close(directory_fd)
                    root_identity()
                root_identity()
            # Same pinned descriptor, not a pathname reopen. Detect in-place
            # mutation even if an attacker supplies internally CRC-valid bytes.
            named=os.stat(source,follow_symlinks=False)
            if signature(os.fstat(source_fd))!=signature(source_initial) or not stat.S_ISREG(named.st_mode) or (named.st_dev,named.st_ino)!=(source_initial.st_dev,source_initial.st_ino) or digest(f)!=expected_sha or signature(os.fstat(source_fd))!=signature(source_initial): raise ValueError('source_digest_changed')
            root_identity()
            return {'zipSha256':expected_sha,'files':len(infos),'bytes':written,'currentArchiveAuthorityVerified':False}
    finally:
        if root_fd is not None: os.close(root_fd)
        if source_fd is not None: os.close(source_fd)
        os.close(parent_fd)

if __name__=='__main__':
    try:
        if len(sys.argv)!=6: raise ValueError('source_arguments')
        result=extract(sys.argv[1],sys.argv[2],sys.argv[3],int(sys.argv[4]),int(sys.argv[5]))
        print(json.dumps(result,separators=(',',':')))
    except Exception:
        print('{"ok":false,"code":"verified_source_extract_failed"}',file=sys.stderr)
        sys.exit(1)
